import json


def safe_json_parse(json_string: str, default: dict = None) -> dict:
    """
    Safely parse a JSON string into a dictionary.

    Args:
        json_string: The JSON string to parse.
        default: The default value to return if parsing fails. Defaults to an empty dict.

    Returns:
        The parsed dictionary, or the default value if parsing fails.
    """
    if default is None:
        default = {}

    if not isinstance(json_string, str):
        return default

    try:
        parsed = json.loads(json_string)
        if isinstance(parsed, dict):
            return parsed
